			desc.pokeID = bpp.GetID();
			desc.reactionType = (byte)ItemReactionBit.BTL_ITEMREACTION_HP;
			GetSectionContainer().GetSection_CheckItemReaction().Execute(result, desc);
		}
		private bool checkExpGet() {
			var desc = new Section_CheckExpGet.Description();
			var result = new Section_CheckExpGet.Result();
			GetSectionContainer().GetSection_CheckExpGet().Execute(result, desc);
			return result.isExpGet;
		}
		public class Description
		{
			public Description() { }
		}
		public class Result
		{
			public bool isExpGet;
			public Result() { }
		}
	}
}
